from itertools import product

N = 13
K = 5  # Pentagon
threshold = N / 2

def solve():
    # Generate all compositions of N into K parts, where each part >= 1
    # We use recursion/backtracking for generating compositions

    compositions = []

    def generate_compositions(k, remaining, current_composition):
        if k == 1:
            if remaining >= 1:
                compositions.append(tuple(current_composition + [remaining]))
            return

        # The minimum value for the next part is 1
        # The maximum value is remaining - (k-1) (must leave at least 1 for each remaining part)
        for d in range(1, remaining - (k - 1) + 1):
            generate_compositions(k - 1, remaining - d, current_composition + [d])

    generate_compositions(K, N, [])

    count_exactly_two_acute = 0

    for d in compositions:
        # Check the angles for this composition d = (d1, d2, d3, d4, d5)

        acute_count = 0

        # Check 5 angles: Angle at V_j is acute if d_{j-1} + d_j > N/2
        # We use cyclic indices: d_0 = d_5, d_6 = d_1
        for j in range(K):
            # j corresponds to the angle at V_{j+1}
            # Neighbors are V_j and V_{j+2}. Side lengths are d_j and d_{j+1}.
            # d_j is the length V_j -> V_{j+1}
            # d_{j+1} is the length V_{j+1} -> V_{j+2}

            d_prev = d[(j - 1) % K]
            d_current = d[j]

            if d_prev + d_current > threshold:
                acute_count += 1

        if acute_count == 2:
            count_exactly_two_acute += 1

    print(f"Total compositions (pentagons): {len(compositions)}")
    print(f"Number of pentagons with exactly two acute angles: {count_exactly_two_acute}")

solve()
